LIB.push(
{t:"Mille sostenitori autentici",c:"eco",tg:"Per vivere del proprio lavoro creativo può bastare un piccolo pubblico davvero affezionato.",d:1,
sp:"Lo scrittore Kevin Kelly ha proposto un'idea semplice: un artista, un artigiano o un piccolo imprenditore non ha bisogno di milioni di clienti. Gli bastano circa mille persone così affezionate da comprare tutto ciò che produce. Mille persone che spendono 100 euro l'anno fanno 100.000 euro. Il modello sposta l'attenzione dal pubblico enorme alla relazione profonda con pochi.",
ap:["Internet permette di raggiungere direttamente le persone giuste, ovunque siano. Invece di inseguire la popolarità, puoi servire bene un gruppo preciso: chi ama le tue ceramiche, chi segue le tue lezioni, chi compra le tue conserve. Questi sostenitori ti fanno anche pubblicità con il passaparola.","Il numero mille è indicativo: dipende da quanto vale ciò che offri e da quanto ti serve per vivere. Il modello funziona se hai un rapporto diretto con i clienti e se produci con continuità. Non funziona se dipendi da intermediari che si prendono gran parte del guadagno."],
ri:[["Inseguire i grandi numeri","Misuri il successo in follower invece che in persone che comprano."],["Clienti che tornano","Alcune persone ti cercano sempre: sono il tuo nucleo."],["Nicchia appassionata","Un piccolo gruppo ama molto ciò che fai."]],
es:[["Lavoro","Un'illustratrice smette di cercare viralità sui social e apre una newsletter. In due anni ha 900 abbonati che comprano le sue stampe e i suoi calendari."],["Te stesso","Un insegnante di chitarra crea un corso online per adulti principianti. Pochi iscritti, ma fedeli, gli permettono di lavorare meno ore."]],
ex:["Calcola quante persone ti servirebbero se ognuna spendesse una certa cifra all'anno per ciò che fai.","Scrivi chi sono i tuoi 10 sostenitori più fedeli e cosa apprezzano di te.","Crea un canale diretto con il tuo pubblico (lista email, gruppo, newsletter) e invita le prime 10 persone."],
q:["Chi sono le persone che amano davvero ciò che faccio?","Ho un rapporto diretto con loro?","Quanto mi serve, e quante persone servono per arrivarci?"],
er:"Trascurare i sostenitori fedeli per inseguire un pubblico enorme e distratto.",
qz:[["Qual è l'idea centrale dei mille sostenitori autentici?",["Servono milioni di follower","Un piccolo pubblico molto fedele può bastare per vivere del proprio lavoro","Bisogna vendere a tutti","Il prezzo deve essere basso"],1,"Conta la profondità del rapporto, non la quantità."],["Cosa rende il modello più difficile?",["Avere un rapporto diretto con i clienti","Dipendere da intermediari che trattengono gran parte del guadagno","Produrre con continuità","Avere una nicchia"],1,"Gli intermediari riducono quanto ti arriva da ogni sostenitore."]]},

{t:"Le quattro P del marketing",c:"lav",tg:"Prodotto, prezzo, posto e promozione: quattro leve da far lavorare insieme.",d:1,
sp:"Le quattro P sono un modo semplice per pensare a come proporre qualcosa agli altri: il Prodotto (cosa offri), il Prezzo (quanto costa), il Posto (dove e come si trova) e la Promozione (come lo fai conoscere). Se una delle quattro non funziona, le altre non bastano. Il modello è nato per il commercio ma serve anche per un'idea, un evento o un progetto personale.",
ap:["Il professore E. Jerome McCarthy rese popolare questo schema negli anni Sessanta. Il punto non è riempire quattro caselle, ma verificare che siano coerenti: un prodotto di lusso venduto in un discount, o un servizio economico promosso con pubblicità costose, crea confusione.","Usalo come lista di controllo: davanti a qualcosa che non vende o non attira, chiediti quale P è debole. Spesso il problema non è il prodotto ma il posto (non si trova) o la promozione (nessuno lo sa)."],
ri:[["Buon prodotto, poche vendite","Il problema è probabilmente in un'altra P."],["Messaggi incoerenti","Prezzo, posto e promozione raccontano storie diverse."],["Lancio di qualcosa di nuovo","Devi decidere come proporlo agli altri."]],
es:[["Lavoro","Un panificio fa ottimo pane ma è in una via nascosta. Cura il posto: cartello all'angolo e consegna in ufficio. Le vendite crescono."],["Te stesso","Organizzi un corso di yoga nel quartiere. Prodotto: lezione per principianti. Prezzo: prima prova gratis. Posto: la sala della parrocchia. Promozione: volantini in farmacia."]],
ex:["Scegli qualcosa che offri (lavoro, servizio, idea) e descrivi le tue quattro P in una riga ciascuna.","Trova la P più debole e scrivi una piccola azione per migliorarla.","Analizza un prodotto che ami: come sono coerenti le sue quattro P?"],
q:["Cosa offro esattamente e a chi?","Il prezzo, il posto e la promozione sono coerenti con il prodotto?","Quale delle quattro P è il punto debole?"],
er:"Concentrarsi solo sul prodotto pensando che si venda da solo.",
qz:[["Quali sono le quattro P?",["Prodotto, prezzo, posto, promozione","Persone, processi, prezzo, pubblicità","Piano, progetto, profitto, prova","Prodotto, pubblico, posto, potere"],0,"Sono le quattro leve classiche del marketing."],["Un buon prodotto non vende perché nessuno lo conosce. Quale P va migliorata?",["Prodotto","Prezzo","Promozione","Nessuna"],2,"Il problema è farlo conoscere."]]},

{t:"Le cinque fasi di un gruppo",c:"evo",tg:"Ogni gruppo nuovo passa per formazione, conflitto, regole, lavoro e chiusura.",d:2,
sp:"Lo psicologo Bruce Tuckman ha descritto le fasi che attraversa un gruppo: formazione (ci si conosce, tutti educati), conflitto (emergono differenze e tensioni), definizione delle regole (si trova un modo di lavorare), prestazione (il gruppo funziona bene) e scioglimento (il lavoro finisce). Sapere che il conflitto è una fase normale aiuta a non spaventarsi e a guidare il gruppo verso la fase successiva.",
ap:["Nelle prime settimane i gruppi sembrano armoniosi perché nessuno espone le proprie idee. Poi arrivano le discussioni su ruoli, metodi e priorità. Molti gruppi si bloccano qui o evitano il conflitto, restando superficiali. Chi lo attraversa con rispetto costruisce regole condivise e diventa molto più efficace.","Ogni volta che entra una persona nuova o cambia l'obiettivo, il gruppo può tornare indietro di una fase. Chi guida dovrebbe adattarsi: dare chiarezza all'inizio, mediare nel conflitto, fissare accordi, poi lasciare autonomia."],
ri:[["Educazione eccessiva","Nessuno dice cosa pensa davvero."],["Tensioni improvvise","Dopo un inizio tranquillo arrivano le discussioni."],["Gruppo che cambia","Entra o esce qualcuno e gli equilibri si rompono."]],
es:[["Lavoro","Un nuovo team litiga sulle scadenze al secondo mese. La responsabile capisce che è la fase del conflitto e organizza un incontro per scrivere le regole di lavoro."],["Te stesso","In un gruppo di volontari le prime discussioni sembrano la fine. Sapendo che è una fase, restate e trovate un metodo comune."]],
ex:["Pensa a un gruppo di cui fai parte: in quale delle cinque fasi si trova?","Se il tuo gruppo è nella fase del conflitto, proponi di scrivere insieme tre regole di lavoro.","Ripensa a un gruppo che si è sciolto: avete chiuso bene, riconoscendo ciò che avete fatto?"],
q:["In quale fase si trova questo gruppo?","Il conflitto che vedo è una fase normale o un problema serio?","Cosa serve per passare alla fase successiva?"],
er:"Evitare ogni conflitto: il gruppo resta in superficie e non diventa mai efficace.",
qz:[["Un gruppo nuovo inizia a litigare dopo poche settimane. Cosa dice il modello?",["Il gruppo è fallito","È una fase normale da attraversare definendo regole","Bisogna sostituire tutti","Bisogna ignorare il problema"],1,"Il conflitto è la seconda fase tipica."],["Cosa succede quando entra un nuovo membro?",["Nulla","Il gruppo può tornare a una fase precedente","Il gruppo si scioglie","Aumenta subito la prestazione"],1,"Gli equilibri vanno ricostruiti."]]},

{t:"I cinque perché",c:"rag",tg:"Chiedi «perché?» più volte di fila per arrivare alla causa vera di un problema.",d:1,
sp:"Quando qualcosa va storto, la prima spiegazione è spesso solo un sintomo. La tecnica dei cinque perché, usata nelle fabbriche Toyota, consiste nel chiedere «perché?» più volte di seguito, finché arrivi a una causa su cui puoi agire davvero. Il numero cinque è indicativo: a volte bastano tre domande, a volte ne servono di più.",
ap:["Esempio: l'auto non parte. Perché? La batteria è scarica. Perché? L'alternatore non la ricarica. Perché? La cinghia è rotta. Perché? Era consumata. Perché? Non è stata controllata durante la manutenzione. La soluzione vera non è cambiare la batteria, ma programmare i controlli.","Il limite è che i problemi complessi hanno spesso più cause, non una catena unica. Conviene fare l'esercizio con altre persone, verificare ogni risposta con i fatti e fermarsi quando trovi una causa che dipende da un processo, non da una persona da incolpare."],
ri:[["Problemi che ritornano","Risolvi un guasto e dopo un po' si ripresenta."],["Soluzioni tampone","Rimedi in fretta senza capire l'origine."],["Colpa a una persona","Ti fermi a «è colpa di Marco»."]],
es:[["Casa","Arrivi sempre in ritardo al lavoro. Perché? Esci tardi. Perché? Cerchi le chiavi. Perché? Non hanno un posto fisso. Soluzione: un gancio vicino alla porta."],["Lavoro","I clienti si lamentano dei ritardi. Chiedendo cinque volte perché, il gruppo scopre che gli ordini arrivano via email e nessuno li controlla il venerdì."]],
ex:["Scegli un piccolo problema ricorrente e scrivi la catena dei cinque perché.","Fai l'esercizio con un'altra persona su un problema comune e confrontate le risposte.","Quando la catena arriva a una persona da incolpare, chiedi ancora un perché sul processo."],
q:["Perché è successo, davvero?","Questa risposta è un fatto o un'ipotesi?","Ho trovato una causa su cui posso agire?"],
er:"Fermarsi alla prima risposta o cercare un colpevole invece di una causa.",
qz:[["A cosa servono i cinque perché?",["A trovare un colpevole","A risalire dalla causa apparente alla causa vera","A perdere tempo","A fare domande ai bambini"],1,"Ogni perché scava un livello più a fondo."],["Qual è un limite della tecnica?",["È troppo lenta","I problemi complessi possono avere più cause, non una catena sola","Funziona solo in fabbrica","Non ha limiti"],1,"Conviene verificare con i fatti e considerare più rami."]]},

{t:"Le sette P delle riunioni",c:"lav",tg:"Scopo, risultato, persone, partecipazione, problemi probabili, processo e aspetti pratici.",d:1,
sp:"Molte riunioni sono inutili perché nessuno le ha preparate. Le sette P sono una lista di controllo per prepararne una buona: Proposito (perché ci troviamo), Prodotto (cosa avremo alla fine), Persone (chi serve davvero), Partecipazione (come coinvolgerle), Problemi probabili (cosa potrebbe andare storto), Processo (la scaletta) e aspetti Pratici (luogo, orario, strumenti).",
ap:["La P più importante è il prodotto: una riunione deve finire con qualcosa di concreto, come una decisione, un elenco di idee o un piano. Se non sai dire quale sarà il risultato, forse basta una mail.","Preparare le sette P richiede dieci minuti e può far risparmiare ore a tutti. Funziona anche per incontri informali: una cena di famiglia per decidere le vacanze o un incontro tra vicini."],
ri:[["Riunioni senza risultato","Si parla molto e non si decide nulla."],["Persone inutili presenti","Metà dei partecipanti non serve."],["Sempre gli stessi a parlare","Gli altri restano in silenzio."]],
es:[["Lavoro","Prima di una riunione scrivi in alto all'invito: «Alla fine avremo scelto il fornitore». La discussione resta concentrata e dura metà del solito."],["Famiglia","Per decidere le vacanze organizzate una cena con scopo chiaro, tre opzioni preparate e un tempo massimo. Si decide in un'ora."]],
ex:["Per la prossima riunione che organizzi, scrivi le sette P in sette righe.","Scrivi il «prodotto» della riunione nell'invito.","Rivedi la lista dei partecipanti e togli chi non serve davvero."],
q:["Cosa avremo in mano alla fine?","Chi serve davvero?","Come faccio parlare anche chi di solito tace?"],
er:"Convocare una riunione senza sapere quale risultato deve produrre.",
qz:[["Quale P indica cosa si ottiene alla fine della riunione?",["Persone","Prodotto","Processo","Pratica"],1,"Il prodotto è il risultato concreto."],["Se non sai quale risultato deve produrre una riunione, cosa suggerisce il modello?",["Farla più lunga","Valutare se basta una mail","Invitare più persone","Farla subito"],1,"Senza un prodotto chiaro la riunione rischia di essere inutile."]]},

{t:"Migliorare togliendo",c:"rag",tg:"Spesso la soluzione migliore è eliminare qualcosa, non aggiungere.",d:2,
sp:"Davanti a un problema tendiamo ad aggiungere: un'altra regola, un altro oggetto, un'altra attività. Le ricerche di Leidy Klotz mostrano che quasi non consideriamo l'opzione di togliere. Il modello ti invita a chiederti prima di tutto: cosa posso eliminare? Spesso togliere semplifica, costa meno e funziona meglio.",
ap:["In un esperimento alle persone veniva chiesto di stabilizzare una struttura di mattoncini. La maggior parte aggiungeva pezzi, anche se togliere un mattoncino era più semplice ed economico. Lo stesso accade nelle agende piene, nelle case affollate, nei processi complicati.","Per usarlo, aggiungi la domanda «cosa tolgo?» a ogni decisione. Elimina riunioni, passaggi, oggetti, impegni. Un'antica idea simile è la via negativa: migliorare evitando ciò che fa male, più che aggiungendo ciò che fa bene."],
ri:[["Agenda piena","Aggiungi impegni senza toglierne."],["Regole su regole","Ogni problema genera una nuova procedura."],["Spazi affollati","Casa o scrivania piene di cose."]],
es:[["Lavoro","Per ridurre gli errori nelle pratiche, invece di un nuovo controllo si eliminano due campi inutili del modulo. Gli errori calano."],["Salute","Invece di aggiungere integratori, togli le bevande zuccherate. Il beneficio è maggiore e costa meno."]],
ex:["Per un problema attuale, scrivi tre cose che potresti togliere invece di aggiungere.","Elimina un impegno ricorrente dalla tua settimana.","Togli dieci oggetti da una stanza e osserva come cambia."],
q:["Cosa posso togliere?","Questa aggiunta risolve il problema o lo complica?","Cosa smetterei di fare se partissi da zero?"],
er:"Togliere ciò che regge il sistema. Prima di eliminare, capisci a cosa serve.",
qz:[["Cosa mostrano le ricerche sul migliorare togliendo?",["Le persone tolgono troppo","Le persone tendono ad aggiungere e trascurano l'opzione di togliere","Togliere è sempre sbagliato","Aggiungere costa meno"],1,"Togliere è un'opzione spesso dimenticata."],["Vuoi una giornata meno stressante. Quale azione segue il modello?",["Aggiungere un'app di produttività","Eliminare un impegno inutile","Svegliarsi prima","Fare più pause caffè"],1,"Togliere riduce il carico."]]},

{t:"ADKAR: accompagnare il cambiamento",c:"app",tg:"Consapevolezza, desiderio, conoscenza, capacità e rinforzo: i cinque passi di ogni cambiamento.",d:2,
sp:"Il modello ADKAR, creato da Jeff Hiatt, dice che una persona cambia davvero solo se attraversa cinque passi: Consapevolezza (capisco perché serve cambiare), Desiderio (voglio cambiare), Conoscenza (so come fare), Capacità (riesco a farlo nella pratica) e Rinforzo (il cambiamento viene sostenuto nel tempo). Se un cambiamento si blocca, cerca il passo mancante.",
ap:["Molti cambiamenti falliscono perché si salta direttamente alla formazione (conoscenza) senza aver creato consapevolezza e desiderio. Oppure si spiega tutto bene ma non si dà tempo di fare pratica, o non si rinforza il nuovo comportamento e le persone tornano alle vecchie abitudini.","Il modello funziona per le organizzazioni ma anche per te stesso o per la tua famiglia. Davanti a un cambiamento che non parte, chiediti: qual è il primo passo che manca? Lavora su quello prima di passare al successivo."],
ri:[["Formazione che non cambia nulla","Le persone sanno, ma non fanno."],["Resistenza","Le persone non vedono il motivo del cambiamento."],["Ritorno al vecchio","Dopo un po' tutto torna come prima."]],
es:[["Lavoro","Un'azienda introduce un nuovo software e organizza corsi. Nessuno lo usa. Mancavano consapevolezza e desiderio: nessuno aveva spiegato quali problemi risolveva."],["Famiglia","Vuoi che i figli riordinino la camera. Spieghi perché (consapevolezza), trovi una ricompensa (desiderio), mostri come (conoscenza), fate insieme (capacità), lodi i progressi (rinforzo)."]],
ex:["Scegli un cambiamento che vuoi fare e dai un voto da 1 a 5 a ciascuno dei cinque passi.","Individua il primo passo debole e scrivi un'azione per rafforzarlo.","Pensa a un cambiamento fallito in passato: quale passo mancava?"],
q:["La persona capisce perché serve cambiare?","Lo vuole davvero?","Sa come fare, riesce a farlo, e qualcosa la sostiene nel tempo?"],
er:"Saltare subito alla formazione senza creare consapevolezza e desiderio.",
qz:[["Cosa significa la R di ADKAR?",["Risorse","Rinforzo","Risultato","Regole"],1,"Il rinforzo sostiene il cambiamento nel tempo."],["Le persone conoscono il nuovo metodo ma non lo usano. Cosa può mancare?",["Conoscenza","Desiderio o capacità pratica","Consapevolezza del software","Nulla"],1,"Sapere non basta: servono volontà e pratica."]]},

{t:"L'effetto del dare consigli",c:"app",tg:"Dare un consiglio a qualcun altro aumenta la tua motivazione a seguirlo.",d:2,
sp:"Di solito pensiamo che chi è in difficoltà abbia bisogno di ricevere consigli. Le ricerche di Lauren Eskreis-Winkler mostrano un effetto sorprendente: chi dà un consiglio diventa più motivato e sicuro di sé, anche più di chi lo riceve. Spiegare agli altri cosa fare ci ricorda ciò che sappiamo e ci impegna a farlo anche noi.",
ap:["In uno studio, studenti in difficoltà a cui veniva chiesto di dare consigli a compagni più giovani studiavano di più rispetto a quelli che ricevevano consigli da esperti. Dare un consiglio ti mette nel ruolo di chi sa, aumenta la fiducia e crea coerenza tra ciò che dici e ciò che fai.","Puoi usarlo su te stesso: se vuoi risparmiare, fare sport o studiare, prova a dare consigli a qualcuno con lo stesso obiettivo. Ma resta onesto: i consigli devono essere sensati, e l'effetto non sostituisce l'azione."],
ri:[["Ti senti bloccato","Pensi di aver bisogno solo di aiuto dagli altri."],["Sai più di quanto credi","Hai già esperienza ma non la usi."],["Gruppi di pari","Persone con lo stesso obiettivo."]],
es:[["Salute","Vuoi smettere di fumare. Ti offri di dare consigli a un amico che vuole fare lo stesso. Spiegandoglieli, ti senti più impegnato."],["Studio","Uno studente fa da tutor a uno più giovane. I suoi voti migliorano perché ripassa e si sente più capace."]],
ex:["Scegli un tuo obiettivo e scrivi tre consigli che daresti a un amico con lo stesso obiettivo. Poi seguili.","Questa settimana offri un consiglio pratico a qualcuno su un tema che conosci.","Crea o unisciti a un piccolo gruppo dove ognuno consiglia gli altri."],
q:["Che consiglio darei a un amico in questa situazione?","Sto già seguendo il consiglio che darei?","A chi potrei offrire aiuto su questo tema?"],
er:"Dare consigli senza seguirli: la coerenza è ciò che produce l'effetto.",
qz:[["Cosa mostrano le ricerche sull'effetto del dare consigli?",["Solo chi riceve consigli migliora","Anche chi dà consigli diventa più motivato","I consigli non servono","Bisogna evitare di consigliare"],1,"Dare consigli aumenta motivazione e fiducia."],["Come usare il modello per un tuo obiettivo?",["Chiedere consigli a tutti","Dare consigli a qualcuno con lo stesso obiettivo","Leggere di più","Aspettare"],1,"Consigliare ti impegna a fare."]]},

{t:"Metodo agile",c:"lav",tg:"Lavora in cicli brevi, consegna spesso, ascolta il feedback e correggi.",d:2,
sp:"Il metodo agile nasce nello sviluppo software, con il Manifesto Agile del 2001. Invece di pianificare tutto all'inizio e consegnare dopo mesi, si lavora in cicli brevi, si consegna qualcosa di utile spesso, si ascolta chi lo usa e si corregge la rotta. È utile ogni volta che il risultato finale non è chiaro fin dall'inizio.",
ap:["I principi chiave sono: le persone e il dialogo contano più dei processi rigidi, qualcosa di funzionante conta più di documenti perfetti, la collaborazione con il cliente conta più dei contratti, rispondere al cambiamento conta più che seguire un piano.","Nella vita quotidiana puoi applicarlo ai progetti personali: invece di preparare tutto per mesi, fai una prima versione in una settimana, mostrala, raccogli reazioni e migliora. Non è adatto quando un errore è molto costoso e non si può correggere dopo."],
ri:[["Piani che invecchiano","Quando finisci, le esigenze sono cambiate."],["Feedback tardivo","Scopri cosa non va solo alla fine."],["Requisiti poco chiari","Nessuno sa esattamente cosa vuole."]],
es:[["Lavoro","Un gruppo deve creare un nuovo sito. Invece di sei mesi di lavoro, pubblica ogni due settimane una parte e la fa provare ai clienti."],["Casa","Ristrutturi casa una stanza alla volta, vivendo ogni stanza prima di decidere la successiva."]],
ex:["Prendi un progetto lungo e definisci una prima versione utile da completare in una settimana.","Mostra la prima versione a due persone e chiedi un commento.","Organizza la prossima settimana in un ciclo: obiettivo il lunedì, revisione il venerdì."],
q:["Qual è la versione più piccola utile che posso consegnare?","Chi può darmi un riscontro presto?","Cosa ho imparato in questo ciclo?"],
er:"Usare l'agilità come scusa per non pianificare nulla.",
qz:[["Cosa caratterizza il metodo agile?",["Un piano dettagliato fisso","Cicli brevi, consegne frequenti e correzioni","Nessun obiettivo","Lavorare da soli"],1,"Si impara dal feedback continuo."],["Quando l'agile è meno adatto?",["Quando i requisiti cambiano","Quando un errore è molto costoso e non correggibile","Nei progetti personali","Nei piccoli gruppi"],1,"Serve la possibilità di correggere."]]},

{t:"Lavorare a ritroso dal cliente",c:"lav",tg:"Parti dall'esperienza che vuoi dare a chi usa il risultato, poi costruisci all'indietro.",d:2,
sp:"Amazon ha reso famoso un metodo: prima di creare un prodotto, si scrive il comunicato stampa del giorno del lancio e le domande frequenti dei clienti. Se il comunicato non entusiasma, il progetto si ferma. Lavorare a ritroso significa partire da cosa vuole e cosa vivrà la persona che userà il risultato, e solo dopo decidere come costruirlo.",
ap:["Spesso partiamo da ciò che sappiamo fare o da ciò che ci piace, e solo alla fine ci chiediamo se a qualcuno serve. Scrivere in anticipo come il risultato cambierà la vita dell'utente obbliga a chiarire il problema, il beneficio e le obiezioni.","Puoi applicarlo a qualsiasi progetto: un corso, un evento, un regalo, una presentazione. Scrivi come vuoi che si senta la persona alla fine, poi chiediti cosa serve per arrivarci."],
ri:[["Progetti che partono dalla tecnologia","«Abbiamo questo strumento, cosa possiamo farci?»."],["Prodotti che nessuno usa","Il risultato è tecnicamente buono ma non serve."],["Obiettivi vaghi","Non sai descrivere il beneficio per l'utente."]],
es:[["Lavoro","Prima di creare un nuovo servizio, il gruppo scrive una pagina come se fosse già lanciato. Scopre che il beneficio non è chiaro e cambia idea."],["Famiglia","Organizzando una festa per un amico, scrivi prima come vorresti che si sentisse uscendo. Ne nasce una festa più intima e meno costosa."]],
ex:["Per un tuo progetto, scrivi un breve annuncio come se fosse già concluso, dal punto di vista di chi ne beneficia.","Scrivi le cinque domande che una persona farebbe sul tuo progetto e rispondi.","Per un regalo o un evento, descrivi prima l'emozione che vuoi creare."],
q:["Chi userà il risultato, e cosa cambierà per lui?","Il mio annuncio entusiasmerebbe qualcuno?","Quali obiezioni o domande avrebbe?"],
er:"Scrivere un annuncio entusiasta e ignorare le domande scomode.",
qz:[["Cosa si scrive per primo con questo metodo?",["Il codice","Il comunicato del lancio e le domande dei clienti","Il budget","Il nome del prodotto"],1,"Si parte dall'esperienza del cliente."],["Perché è utile?",["Fa risparmiare carta","Obbliga a chiarire il beneficio prima di costruire","Sostituisce la ricerca","Garantisce il successo"],1,"Rende evidente se il progetto serve davvero."]]},

{t:"Euristica dell'ancoraggio",c:"rag",tg:"Il primo numero che senti influenza le stime e le decisioni successive.",d:2,
sp:"Quando dobbiamo stimare un valore, partiamo dal primo numero disponibile, l'àncora, e ci spostiamo troppo poco da lì. Il primo prezzo in una trattativa, uno sconto barrato, una cifra detta per caso: tutto ci ancora. Gli psicologi Amos Tversky e Daniel Kahneman hanno mostrato che anche un numero casuale influenza le stime.",
ap:["In un esperimento le persone facevano girare una ruota con numeri casuali e poi stimavano la percentuale di Paesi africani all'ONU. Chi aveva visto un numero alto dava stime più alte. Nella vita: il prezzo «prima» barrato rende interessante il prezzo «dopo», la prima offerta di stipendio guida tutta la trattativa.","Per difenderti, prima di sentire numeri fatti una tua stima indipendente. In una trattativa, considera di fare tu la prima proposta, ben motivata. E quando vedi un numero, chiediti: da dove viene? È rilevante?"],
ri:[["Prezzi barrati","«Prima 199, ora 99»."],["Prime offerte","La trattativa ruota attorno al primo numero detto."],["Stime influenzate","Un numero precedente ti guida senza motivo."]],
es:[["Acquisti","Vedi una giacca a 300 euro e poi una a 150: ti sembra economica. Ti chiedi quanto avresti speso senza vedere la prima."],["Lavoro","Al colloquio ti chiedono quanto guadagni ora. Invece di dirlo, indichi una cifra basata sul valore del ruolo."]],
ex:["Prima del prossimo acquisto importante, scrivi quanto sei disposto a spendere prima di guardare i prezzi.","In una trattativa, prepara un primo numero motivato da proporre tu.","Nota tre àncore questa settimana (pubblicità, menu, offerte) e come ti influenzano."],
q:["Quale numero mi sta ancorando?","Quanto avrei stimato senza sentirlo?","Da dove viene questo numero ed è rilevante?"],
er:"Pensare di essere immuni: l'àncora funziona anche quando la riconosci.",
qz:[["Cos'è l'ancoraggio?",["Restare fermi","Farsi influenzare dal primo numero sentito","Scegliere il prezzo più basso","Fidarsi dei venditori"],1,"Il primo numero orienta le stime successive."],["Come difendersi in una trattativa?",["Aspettare sempre l'offerta altrui","Fare una propria stima prima e, se utile, proporre per primi","Non trattare","Accettare la prima offerta"],1,"Così l'àncora è tua."]]},

{t:"Architetti e giardinieri",c:"com",tg:"Alcuni pianificano tutto prima, altri scoprono la strada facendo: conosci il tuo stile.",d:1,
sp:"Lo scrittore George R. R. Martin distingue due tipi di autori: gli architetti, che progettano tutta la storia prima di scrivere, e i giardinieri, che piantano un'idea e la vedono crescere scrivendo. Il modello vale per qualsiasi progetto: entrambi gli stili funzionano, ma è utile sapere qual è il tuo e quando conviene usare l'altro.",
ap:["Gli architetti hanno chiarezza e meno vicoli ciechi, ma rischiano rigidità e paralisi da pianificazione. I giardinieri sono flessibili e scoprono idee impreviste, ma rischiano di perdersi o non finire. La maggior parte delle persone è un misto.","Nei progetti con scadenze, budget o tante persone conviene una struttura da architetto. Nei progetti creativi o nuovi, lo spazio del giardiniere aiuta a scoprire. Un buon compromesso: una mappa di massima e libertà nei dettagli."],
ri:[["Bloccato nella pianificazione","Non inizi finché il piano non è perfetto."],["Progetti che si perdono","Inizi con entusiasmo ma non sai dove vai."],["Conflitti di stile","In coppia o in gruppo uno pianifica, l'altro improvvisa."]],
es:[["Lavoro","In un gruppo, una collega vuole un piano dettagliato e un'altra vuole provare subito. Decidono una struttura in tre fasi con libertà dentro ciascuna."],["Viaggi","Tu prenoti tutto, il partner vorrebbe improvvisare. Fissate alloggi e voli, e lasciate libere le giornate."]],
ex:["Rifletti: in quali situazioni sei più architetto e in quali più giardiniere?","Per un progetto in corso, prova lo stile opposto al tuo per una settimana.","Con chi lavori o vivi, parla del vostro stile e trovate un compromesso."],
q:["Sono architetto o giardiniere in questo progetto?","Questo progetto ha bisogno di più struttura o di più libertà?","Come combino una mappa generale con spazio per scoprire?"],
er:"Pensare che il proprio stile sia l'unico giusto.",
qz:[["Cosa fa un giardiniere secondo il modello?",["Pianifica tutto prima","Scopre la strada facendo","Non lavora","Copia gli altri"],1,"Pianta un'idea e la fa crescere."],["Quando serve di più lo stile da architetto?",["Nei progetti creativi liberi","Nei progetti con scadenze, budget e molte persone","Mai","Solo nella scrittura"],1,"La struttura aiuta a coordinare."]]},

{t:"La retorica di Aristotele",c:"com",tg:"Per convincere servono credibilità, emozione e logica.",d:2,
sp:"Aristotele descrisse tre modi per persuadere: l'ethos, cioè la credibilità di chi parla; il pathos, cioè le emozioni del pubblico; e il logos, cioè la logica e le prove. I discorsi più efficaci li usano tutti e tre in equilibrio. Il modello ti aiuta a costruire messaggi più convincenti e a riconoscere come gli altri cercano di convincerti.",
ap:["Senza ethos, non ti ascoltano: perché dovrebbero fidarsi di te? Senza pathos, ti ascoltano ma non si muovono: i fatti da soli raramente spingono all'azione. Senza logos, puoi emozionare, ma alla prima obiezione il discorso crolla.","Prima di una presentazione o di una richiesta, chiediti: cosa mi rende credibile su questo tema? Quale emozione o bisogno tocca il mio pubblico? Quali prove posso portare? Quando sei tu a essere persuaso, chiediti quale dei tre ti sta convincendo e se basta."],
ri:[["Solo numeri","Una presentazione piena di dati che non smuove nessuno."],["Solo emozione","Un messaggio commovente senza prove."],["Nessuna fiducia","Il pubblico non sa perché dovrebbe ascoltarti."]],
es:[["Lavoro","Chiedi un budget per un progetto. Presenti la tua esperienza (ethos), una storia di un cliente in difficoltà (pathos) e i numeri del ritorno previsto (logos)."],["Famiglia","Vuoi convincere i genitori anziani a usare il bastone. Ricordi che lo consiglia il medico (ethos), parli della loro libertà di uscire (pathos) e del rischio di cadute (logos)."]],
ex:["Prepara una richiesta che devi fare e scrivi una frase per ethos, una per pathos e una per logos.","Analizza una pubblicità: quale dei tre usa di più?","Riguarda una tua presentazione recente: quale elemento mancava?"],
q:["Perché dovrebbero fidarsi di me su questo?","Quale emozione o bisogno tocca il mio messaggio?","Quali prove porto?"],
er:"Usare il pathos per manipolare: la fiducia persa non si recupera facilmente.",
qz:[["Cos'è il logos?",["La credibilità","L'emozione","La logica e le prove","Il tono di voce"],2,"Il logos è l'argomentazione razionale."],["Una presentazione piena di dati non convince. Cosa manca probabilmente?",["Logos","Pathos o ethos","Più dati","Nulla"],1,"I fatti da soli raramente spingono all'azione."]]},

{t:"Euristica della disponibilità",c:"rag",tg:"Giudichiamo più probabile ciò che ci viene in mente più facilmente.",d:2,
sp:"Quando stimiamo quanto è frequente un evento, ci basiamo su quanto facilmente ci vengono in mente esempi. Gli eventi recenti, drammatici o raccontati spesso dai media sembrano più probabili di quanto siano. Per questo temiamo gli attacchi di squalo più delle cadute in casa, che sono molto più frequenti.",
ap:["Tversky e Kahneman hanno descritto questa scorciatoia mentale. È utile perché spesso ciò che ricordiamo facilmente è davvero frequente. Ma i ricordi sono distorti da emozioni, notizie e esperienze personali: un incidente visto da vicino pesa più di mille statistiche.","Per correggerla, cerca i dati invece di affidarti agli esempi che ricordi. Chiediti: lo penso perché è frequente o perché ne ho sentito parlare? Cosa non mi viene in mente perché non fa notizia?"],
ri:[["Paure sproporzionate","Temi eventi rari e spettacolari."],["Influenza delle notizie","Dopo un fatto di cronaca ti sembra che succeda ovunque."],["Esperienze personali","Un caso vissuto diventa la regola."]],
es:[["Salute","Dopo aver letto di un raro effetto collaterale, rinunci a una cura utile. Controllando i dati, scopri che il rischio è minimo rispetto al beneficio."],["Lavoro","Il capo ricorda solo l'ultimo errore di un collega e dimentica mesi di buon lavoro. Una valutazione con dati di tutto l'anno corregge il giudizio."]],
ex:["Scegli una tua paura e cerca il dato reale sulla sua frequenza.","Prima di giudicare qualcuno, scrivi esempi di tutto il periodo, non solo i più recenti.","Dopo una notizia allarmante, chiediti quanto è comune davvero quell'evento."],
q:["Lo penso perché è frequente o perché è facile da ricordare?","Cosa dicono i dati?","Quali casi non mi vengono in mente perché non fanno notizia?"],
er:"Fidarsi solo degli esempi vividi e ignorare le statistiche noiose.",
qz:[["Perché molte persone temono più l'aereo dell'auto?",["L'aereo è più pericoloso","Gli incidenti aerei sono rari ma molto raccontati","Le auto non hanno incidenti","Per caso"],1,"Gli eventi drammatici sono più facili da ricordare."],["Come correggere l'euristica della disponibilità?",["Ascoltare più notizie","Cercare i dati reali sulla frequenza","Fidarsi dell'istinto","Evitare di pensarci"],1,"I dati compensano i ricordi distorti."]]},

{t:"La scheda di valutazione bilanciata",c:"lav",tg:"Misura i risultati da quattro punti di vista, non solo dai soldi.",d:2,
sp:"Robert Kaplan e David Norton hanno proposto di valutare un'organizzazione da quattro prospettive: risultati economici, soddisfazione dei clienti, qualità dei processi interni, apprendimento e crescita delle persone. Guardare solo i soldi mostra il passato; le altre tre prospettive indicano cosa succederà dopo.",
ap:["Un'azienda può avere ottimi conti quest'anno mentre perde clienti, accumula problemi nei processi e non forma le persone. Tra un anno i conti peggioreranno. La scheda bilanciata obbliga a scegliere pochi indicatori per ciascuna area e a collegarli alla strategia.","Puoi usarla anche per la tua vita o la tua famiglia: soldi, relazioni, salute e crescita personale. Se un'area va bene a spese delle altre, prima o poi lo squilibrio si paga."],
ri:[["Solo indicatori economici","Si guarda solo il fatturato."],["Problemi che arrivano dopo","I conti vanno bene, ma il clima è pessimo."],["Obiettivi scollegati","Ogni reparto misura cose diverse."]],
es:[["Lavoro","Un negozio misura vendite, recensioni dei clienti, tempi di attesa alla cassa e ore di formazione del personale. Scopre che le attese lunghe fanno perdere clienti."],["Te stesso","Crei una scheda personale: risparmio mensile, tempo con gli amici, ore di sonno, libri letti. Ogni mese vedi dove sei squilibrato."]],
ex:["Crea la tua scheda personale con un indicatore per ciascuna delle quattro aree.","Per il tuo lavoro, scrivi un indicatore che oggi nessuno guarda ma che anticipa i problemi.","Valuta l'ultimo mese: quale area hai sacrificato?"],
q:["Sto guardando solo il risultato economico?","Quale indicatore mi avverte prima dei problemi?","Le quattro aree sono in equilibrio?"],
er:"Riempire la scheda di troppi indicatori: ne bastano pochi per area.",
qz:[["Quali sono le quattro prospettive della scheda bilanciata?",["Vendite, costi, tasse, profitti","Economica, clienti, processi interni, apprendimento e crescita","Passato, presente, futuro, rischio","Capo, dipendenti, clienti, fornitori"],1,"Completano la sola visione economica."],["Perché non basta guardare i soldi?",["I soldi non contano","I risultati economici mostrano il passato, le altre aree anticipano il futuro","È vietato","Per moda"],1,"Clienti, processi e persone sono indicatori anticipatori."]]},

{t:"BATNA e ZOPA",c:"eco",tg:"Sappi qual è la tua alternativa migliore e dove si incontrano gli interessi delle parti.",d:3,
sp:"In una trattativa, la BATNA è la tua migliore alternativa se l'accordo salta: più è forte, più puoi trattare con calma. La ZOPA è la zona di possibile accordo: lo spazio tra il massimo che una parte è disposta a dare e il minimo che l'altra è disposta ad accettare. Se questo spazio non esiste, non c'è accordo possibile.",
ap:["I termini vengono dal libro «L'arte del negoziato» di Roger Fisher e William Ury, del progetto di negoziazione di Harvard. Conoscere la tua BATNA ti dice quando dire no; stimare quella dell'altro ti dice quanto potere ha. Migliorare la tua BATNA prima di trattare è spesso la mossa più efficace.","Per trovare la ZOPA, chiarisci il tuo limite (il punto oltre cui preferisci la tua alternativa) e cerca di capire quello dell'altro. Spesso la zona si allarga se consideri più elementi oltre al prezzo: tempi, condizioni, servizi."],
ri:[["Trattative senza alternative","Ti senti costretto ad accettare."],["Non conosci il tuo limite","Accetti o rifiuti d'istinto."],["Discussione solo sul prezzo","Ignori altri elementi che potrebbero creare accordo."]],
es:[["Lavoro","Prima di chiedere un aumento, fai due colloqui con altre aziende. La tua BATNA migliora e tratti con più sicurezza."],["Casa","Vendi l'auto. Il tuo limite è 8.000 euro perché un concessionario te ne offre 7.800. Il compratore offre 7.500, ma aggiungendo il ritiro a domicilio trovate accordo a 8.200."]],
ex:["Per una trattativa imminente, scrivi la tua BATNA e il tuo limite minimo.","Stima la BATNA dell'altra parte: cosa farebbe senza di te?","Elenca tre elementi oltre al prezzo che potrebbero allargare la zona di accordo."],
q:["Cosa faccio se non troviamo un accordo?","Qual è il mio limite oltre cui preferisco l'alternativa?","Esiste uno spazio comune, e come posso allargarlo?"],
er:"Entrare in una trattativa senza conoscere la propria alternativa.",
qz:[["Cos'è la BATNA?",["Il prezzo ideale","La migliore alternativa se l'accordo non si fa","Un tipo di contratto","La prima offerta"],1,"Definisce quando conviene dire no."],["Cosa succede se non esiste una ZOPA?",["L'accordo è facile","Non c'è un accordo possibile alle condizioni attuali","Vince chi parla per primo","Si divide a metà"],1,"I limiti delle parti non si sovrappongono."]]},

{t:"La matrice crescita-quota BCG",c:"eco",tg:"Classifica le attività in stelle, mucche da mungere, punti interrogativi e cani.",d:2,
sp:"Il Boston Consulting Group ha creato una matrice per decidere dove investire. Ogni attività viene posizionata secondo due criteri: quanto cresce il suo mercato e quanto è forte la tua posizione. Le stelle (mercato in crescita, posizione forte) vanno sostenute; le mucche da mungere (mercato stabile, posizione forte) generano risorse; i punti interrogativi vanno messi alla prova; i cani (mercato fermo, posizione debole) vanno ripensati.",
ap:["L'idea è che le risorse generate dalle mucche da mungere finanzino le stelle e i punti interrogativi più promettenti. Così un'organizzazione resta equilibrata tra presente e futuro.","Puoi usarla anche per le tue attività personali o professionali: quali competenze ti danno reddito stabile, quali sono in forte crescita, quali sono promesse incerte e quali ti costano tempo senza futuro. Ricorda che è una semplificazione: alcuni «cani» hanno valore strategico."],
ri:[["Risorse disperse","Investi ugualmente in tutto."],["Attività che non rendono","Continui per abitudine."],["Nessun investimento sul futuro","Vivi solo di ciò che rende oggi."]],
es:[["Lavoro","Un ristorante scopre che il pranzo per gli uffici è una mucca da mungere, il servizio di catering è una stella e la colazione è un cane. Sposta risorse sul catering."],["Te stesso","Le tue lezioni private ti danno reddito stabile, il nuovo corso online cresce, un vecchio hobby ti costa molto senza piacere. Riduci il terzo."]],
ex:["Elenca le tue attività (lavoro o tempo libero) e mettile nei quattro quadranti.","Decidi un'attività «cane» da ridurre questo mese.","Scegli una «stella» o un «punto interrogativo» su cui investire più tempo."],
q:["Dove cresce il mercato o l'interesse?","Dove ho una posizione forte?","Le risorse di oggi stanno finanziando il domani?"],
er:"Abbandonare troppo presto i punti interrogativi, che possono diventare stelle.",
qz:[["Cosa rappresenta una «mucca da mungere»?",["Mercato in crescita e posizione debole","Mercato stabile e posizione forte che genera risorse","Mercato fermo e posizione debole","Un'attività nuova"],1,"Genera risorse da reinvestire."],["Cosa fare di solito con i «cani»?",["Investire tutto","Ripensarli o ridurli","Ignorarli","Raddoppiarli"],1,"Hanno mercato fermo e posizione debole."]]},

{t:"Benchmarking: confrontare per imparare",c:"lav",tg:"Osserva chi fa meglio una cosa e impara dal suo metodo.",d:1,
sp:"Il benchmarking consiste nel confrontare i propri risultati e metodi con quelli dei migliori, per capire dove migliorare. Non si tratta di copiare, ma di imparare: scoprire perché qualcuno ottiene risultati migliori e adattare l'idea al proprio contesto. Spesso le idee più utili vengono da settori diversi.",
ap:["Negli anni Ottanta l'azienda Xerox iniziò a confrontarsi con concorrenti e con aziende di altri settori per migliorare. Un esempio classico è guardare come le squadre di Formula 1 cambiano le gomme in pochi secondi per migliorare i tempi di preparazione in una sala operatoria.","Per farlo bene scegli cosa misurare, trova chi lo fa meglio, studia il suo processo e prova a adattarlo. Attenzione al confronto sbagliato: paragonarsi a contesti troppo diversi o solo ai risultati, senza capire il metodo, porta a frustrazione."],
ri:[["Risultati fermi","Non sai cosa migliorare."],["Autoreferenzialità","Ti confronti solo con te stesso."],["Qualcuno fa meglio","Vedi altri ottenere di più con meno."]],
es:[["Casa","Una collega prepara la cena in 20 minuti. Le chiedi come fa: cucina il doppio due volte a settimana. Lo provi anche tu."],["Lavoro","Un ufficio pubblico studia come una catena di caffetterie gestisce le code e introduce i numeri con app."]],
ex:["Scegli un'attività che vuoi migliorare e trova qualcuno che la fa meglio. Chiedigli come fa.","Cerca un esempio da un settore diverso che risolve un problema simile al tuo.","Misura un tuo risultato oggi per poterlo confrontare tra un mese."],
q:["Chi fa questa cosa meglio di me?","Cosa fa di diverso nel metodo, non solo nel risultato?","Come posso adattarlo al mio contesto?"],
er:"Copiare senza capire il contesto, o confrontarsi solo per sentirsi inferiori.",
qz:[["Qual è lo scopo del benchmarking?",["Copiare i concorrenti","Imparare dai migliori e adattare i loro metodi","Criticare gli altri","Vantarsi"],1,"Si confronta per imparare."],["Perché può essere utile guardare altri settori?",["Non è utile","Possono avere soluzioni originali a problemi simili","Sono più famosi","Costa meno"],1,"Le idee migliori spesso vengono da fuori."]]},

{t:"Pensare come una scatola nera",c:"app",tg:"Tratta gli errori come dati da studiare, non come colpe da nascondere.",d:2,
sp:"Gli aerei hanno una scatola nera che registra tutto. Dopo ogni incidente viene analizzata e le lezioni vengono condivise con tutto il settore. Per questo il volo è diventato così sicuro. Matthew Syed propone di applicare lo stesso atteggiamento alla vita: analizzare gli errori in modo aperto, senza cercare colpevoli, per imparare e non ripeterli.",
ap:["In molti ambienti gli errori vengono nascosti per paura di punizioni o per orgoglio. Così si ripetono. Nel trasporto aereo invece segnalare un errore è incoraggiato e protetto. La differenza non è nell'intelligenza, ma nella cultura verso il fallimento.","Per pensare come una scatola nera, dopo un errore chiediti: cosa è successo esattamente? Perché? Cosa cambio nel sistema per evitarlo? Condividi la lezione. E crea intorno a te un clima dove si può ammettere un errore senza essere umiliati."],
ri:[["Errori nascosti","Nessuno ammette di aver sbagliato."],["Stessi problemi ripetuti","Si commettono gli stessi errori."],["Ricerca del colpevole","Dopo un problema si punisce invece di capire."]],
es:[["Lavoro","Dopo un ordine sbagliato, il gruppo fa una riunione di dieci minuti senza colpe: scopre che il modulo era ambiguo e lo corregge."],["Te stesso","Dopo un esame andato male, invece di dire «sono negato», analizzi cosa hai studiato, come e quando. Cambi metodo."]],
ex:["Scegli un errore recente e scrivi: cosa è successo, perché, cosa cambio.","Tieni un «diario degli errori» per un mese, con una lezione per ciascuno.","Racconta a qualcuno un tuo errore e cosa hai imparato."],
q:["Cosa è successo esattamente?","Cosa nel sistema ha reso possibile l'errore?","Quale lezione posso condividere?"],
er:"Analizzare gli errori per trovare un colpevole invece di una causa.",
qz:[["Perché il trasporto aereo è diventato così sicuro?",["Per fortuna","Perché gli errori vengono analizzati e le lezioni condivise","Perché i piloti non sbagliano mai","Perché ci sono pochi voli"],1,"La cultura dell'analisi degli errori lo ha reso sicuro."],["Qual è l'atteggiamento giusto dopo un errore?",["Nasconderlo","Analizzarlo senza cercare colpevoli e cambiare il sistema","Punire","Dimenticarlo"],1,"L'errore diventa un dato da cui imparare."]]},

{t:"Il cigno nero",c:"qua",tg:"Eventi rari, imprevedibili e con effetti enormi, che poi sembrano ovvi.",d:3,
sp:"Per secoli in Europa si credeva che tutti i cigni fossero bianchi, finché in Australia ne furono scoperti di neri. Nassim Taleb usa questa immagine per descrivere eventi rari, imprevedibili e con conseguenze enormi: crisi finanziarie, pandemie, invenzioni rivoluzionarie. Dopo che accadono, ci raccontiamo che erano prevedibili. Il modello ti invita a prepararti a ciò che non puoi prevedere.",
ap:["I cigni neri sfuggono alle previsioni perché non sono nei dati del passato. I modelli basati sulla media li ignorano, ma sono proprio questi eventi a cambiare la storia. Dopo l'evento, il senno di poi ci convince che i segnali c'erano.","Invece di cercare di prevederli, costruisci robustezza: margini di sicurezza, diversificazione, poca esposizione a rischi enormi. E aumenta l'esposizione ai cigni neri positivi: piccole scommesse con grande potenziale, incontri, esperimenti."],
ri:[["«Non è mai successo»","Escludi un evento perché non è nei dati del passato."],["Previsioni troppo sicure","Ti affidi a modelli che ignorano gli estremi."],["Rischi con perdite illimitate","Una scelta può rovinarti in un colpo solo."]],
es:[["Soldi","Una famiglia tiene tutti i risparmi in un'unica azione. Un evento improvviso li dimezza. Diversificare avrebbe limitato il danno."],["Lavoro","Un piccolo negozio con un sito online e un fondo di emergenza supera un lungo periodo di chiusura imprevisto."]],
ex:["Scrivi tre eventi improbabili che potrebbero colpire gravemente la tua vita e un modo per ridurne l'impatto.","Individua una piccola scommessa con potenziale positivo enorme e costo basso.","Rileggi una tua previsione sicura e chiediti cosa potrebbe smentirla completamente."],
q:["Cosa succede se accade qualcosa che non è mai successo?","Sono esposto a perdite enormi?","Dove posso fare piccole scommesse con grande potenziale positivo?"],
er:"Credere di poter prevedere i cigni neri invece di prepararsi alle loro conseguenze.",
qz:[["Cosa caratterizza un cigno nero?",["È frequente e prevedibile","È raro, imprevedibile e ha effetti enormi","Ha effetti piccoli","È sempre negativo"],1,"Ha queste tre caratteristiche."],["Qual è la strategia consigliata?",["Prevedere con precisione","Costruire robustezza e limitare le perdite estreme","Ignorarli","Puntare tutto su un'idea"],1,"Prepararsi conta più che prevedere."]]},

{t:"La strategia dell'oceano blu",c:"eco",tg:"Invece di battere i concorrenti, crea uno spazio dove la concorrenza non conta.",d:2,
sp:"W. Chan Kim e Renée Mauborgne distinguono gli oceani rossi, mercati affollati dove i concorrenti si combattono e il sangue colora l'acqua, dagli oceani blu, spazi nuovi dove la concorrenza è irrilevante. Per crearli bisogna offrire un valore diverso, eliminando alcune cose che il settore dà per scontate e aggiungendone altre che nessuno offre.",
ap:["L'esempio classico è il Cirque du Soleil: tolse gli animali e le star del circo tradizionale, costosi, e aggiunse musica, teatro e trame, attirando un pubblico adulto disposto a pagare di più. Lo strumento chiave sono quattro domande: cosa eliminare, cosa ridurre, cosa aumentare, cosa creare.","Puoi applicarlo alla tua carriera o al tuo lavoro: invece di essere uno dei tanti, chiediti quali convenzioni del tuo settore potresti eliminare e quale valore nuovo potresti offrire."],
ri:[["Guerra dei prezzi","Tutti offrono la stessa cosa e abbassano i prezzi."],["Clienti insoddisfatti dalle offerte attuali","Nessuno serve bene un certo bisogno."],["Convenzioni mai messe in discussione","«Nel nostro settore si fa così»."]],
es:[["Lavoro","Una palestra elimina macchinari costosi e contratti annuali, aggiunge lezioni brevi in pausa pranzo vicino agli uffici. Attira chi non era mai andato in palestra."],["Te stesso","Invece di competere come uno dei tanti grafici, una designer si specializza in menu per ristoranti piccoli, con stampa e foto incluse."]],
ex:["Per il tuo lavoro o progetto, rispondi alle quattro domande: eliminare, ridurre, aumentare, creare.","Individua un gruppo di persone che oggi non usa nessuna offerta del tuo settore e chiediti perché.","Scrivi tre convenzioni del tuo campo che nessuno mette in discussione."],
q:["Cosa posso eliminare che il settore dà per scontato?","Cosa posso creare che nessuno offre?","Chi non è ancora cliente di nessuno, e perché?"],
er:"Pensare che basti essere diversi: il nuovo valore deve interessare davvero qualcuno.",
qz:[["Cos'è un oceano rosso?",["Un mercato nuovo","Un mercato affollato con forte concorrenza","Un mercato senza clienti","Un mercato di lusso"],1,"È lo spazio della concorrenza diretta."],["Quali sono le quattro domande della strategia?",["Chi, cosa, dove, quando","Eliminare, ridurre, aumentare, creare","Costi, ricavi, rischi, tempi","Prodotto, prezzo, posto, promozione"],1,"Servono a ridisegnare l'offerta."]]},

{t:"Le due liste di Buffett",c:"rag",tg:"Scegli le 5 priorità più importanti ed evita attivamente tutte le altre.",d:2,
sp:"Si racconta che Warren Buffett abbia dato questo consiglio al suo pilota: scrivi i tuoi 25 obiettivi principali, cerchia i 5 più importanti, e considera gli altri 20 come una lista di cose da evitare a ogni costo. La storia potrebbe non essere vera alla lettera, ma l'idea è potente: gli obiettivi «abbastanza importanti» sono quelli che ti distraggono di più dai veri obiettivi.",
ap:["Gli obiettivi secondari sono pericolosi proprio perché sono attraenti. Non li abbandoniamo perché ci sembrano utili, e così disperdiamo tempo ed energia. Concentrarsi su pochi obiettivi permette di raggiungerli davvero.","Il modello richiede coraggio: dire no a cose buone. Non significa rinunciarvi per sempre, ma solo finché le priorità principali non sono raggiunte."],
ri:[["Troppi progetti aperti","Lavori su tutto e non finisci nulla."],["Obiettivi in competizione","Ogni settimana cambi priorità."],["Difficoltà a dire no","Accetti tutto ciò che sembra interessante."]],
es:[["Te stesso","Scrivi 20 cose che vorresti fare quest'anno. Ne scegli 4. Rinunci per ora a imparare il pianoforte e a ristrutturare la cantina."],["Lavoro","Un piccolo imprenditore sceglie 3 priorità per il trimestre e rifiuta un nuovo progetto interessante che lo avrebbe distratto."]],
ex:["Scrivi i tuoi 20-25 obiettivi, cerchia i 5 più importanti.","Copia gli altri in una lista «da evitare per ora» e tienila in vista.","Questa settimana di' no a una cosa della seconda lista."],
q:["Quali sono le mie 5 priorità vere?","Quali obiettivi attraenti mi distraggono da queste?","A cosa devo dire no questa settimana?"],
er:"Lavorare un po' sugli obiettivi della seconda lista «solo quando c'è tempo».",
qz:[["Cosa fare con gli obiettivi non scelti tra i primi 5?",["Lavorarci quando possibile","Evitarli finché non raggiungi le priorità","Dimenticarli per sempre","Delegarli tutti"],1,"Sono le distrazioni più pericolose."],["Perché gli obiettivi secondari sono pericolosi?",["Sono inutili","Sono abbastanza attraenti da distrarre dalle priorità","Costano troppo","Sono facili"],1,"Ci rubano energia senza sembrare un problema."]]},

{t:"L'asimmetria delle sciocchezze",c:"com",tg:"Smentire una falsità richiede molta più energia che produrla.",d:2,
sp:"Il programmatore Alberto Brandolini ha formulato una legge: l'energia necessaria per smentire una sciocchezza è molto più grande di quella necessaria per produrla. Inventare una notizia falsa richiede un minuto; verificarla e spiegare perché è falsa può richiedere ore. Il modello aiuta a scegliere quando vale la pena rispondere e a fermare le falsità prima che si diffondano.",
ap:["Questa asimmetria spiega perché le informazioni false circolano così facilmente. Chi le diffonde non deve dimostrare nulla, mentre chi le smentisce deve trovare fonti, spiegare e convincere. Spesso, nel frattempo, la falsità ha già fatto il giro.","Per difendersi conviene prevenire: verificare prima di condividere, scegliere fonti affidabili, insegnare agli altri come riconoscere i trucchi. Non puoi smentire tutto: scegli le battaglie importanti e usa risposte brevi, chiare e con una fonte."],
ri:[["Catene di messaggi","Notizie sensazionali che girano nei gruppi."],["Discussioni infinite","Passi ore a smentire qualcosa detto in un attimo."],["Affermazioni senza fonte","Molta sicurezza e nessuna prova."]],
es:[["Famiglia","Nel gruppo di famiglia circola un falso rimedio. Invece di una lunga discussione, condividi un link breve a una fonte affidabile e una frase gentile."],["Lavoro","Un pettegolezzo infondato si diffonde in ufficio. La responsabile lo chiarisce subito con un messaggio breve prima che cresca."]],
ex:["Prima di condividere una notizia questa settimana, verificane la fonte.","Prepara una risposta breve e gentile per smentire una falsità comune nella tua cerchia.","Scegli una discussione online in cui non entrerai perché non vale lo sforzo."],
q:["Vale la pena spendere energia per smentirlo?","Posso fermarlo prima che si diffonda?","Ho verificato prima di condividere?"],
er:"Cercare di smentire ogni sciocchezza, sprecando tutte le energie.",
qz:[["Cosa dice la legge di Brandolini?",["Le falsità sono rare","Smentire una sciocchezza richiede molta più energia che produrla","Tutti dicono la verità","Le smentite sono veloci"],1,"Produrre falsità costa poco, smentirle molto."],["Qual è la strategia più efficace?",["Smentire tutto","Prevenire verificando e scegliere le battaglie importanti","Ignorare sempre","Condividere tutto"],1,"La prevenzione costa meno della smentita."]]}
);
